//! JSON Schema binding of the CpgSchema contract.
//!
//! The compile-time validators are generated by `jsonschema`.
//! The optional `JsonCpgSchema` adapter implements the same Rust traits as the
//! native representation, so consumers can program against `CpgSchemaContract`.

use crate::{
    contracts::{
        validate_contract, CpgSchemaContract, ContractError,
        PropertyDefaultsContract, SchemaModuleContract,
    },
    json_vocabulary::*,
};
use serde_json::Value;
use std::fmt;

pub const VOCABULARY_META_SCHEMA_JSON: &str =
    include_str!("../schemas/cpg-schema.vocabulary.meta.schema.json");
pub const DIALECT_META_SCHEMA_JSON: &str =
    include_str!("../schemas/cpg-dialect.meta.schema.json");
pub const CPG_SCHEMA_META_SCHEMA_JSON: &str =
    include_str!("../schemas/cpg-schema.meta.schema.json");
pub const CANONICAL_CPG_SCHEMA_JSON: &str =
    include_str!("../schemas/cpg.schema.json");

/// Compiled meta-schema for the JSON representation of CpgSchema.
#[jsonschema::validator(
    path = "schemas/cpg-schema.meta.schema.json",
    draft = Draft202012
)]
pub struct CpgSchemaMetaSchemaValidator;

/// Compiled custom dialect meta-schema.
#[jsonschema::validator(
    path = "schemas/cpg-dialect.meta.schema.json",
    draft = Draft202012,
    resources = {
        "https://shiftleft.io/codepropertygraph/schema/meta/cpg-schema-vocabulary/2026-10" => {
            path = "schemas/cpg-schema.vocabulary.meta.schema.json"
        }
    }
)]
pub struct CpgDialectMetaSchemaValidator;

/// The canonical CPG schema document itself is compiled as a JSON Schema at
/// Rust compile time. Requiring the vocabulary here ensures the compiler knows
/// that this implementation supports the custom CPG vocabulary.
#[jsonschema::validator(
    path = "schemas/cpg.schema.json",
    resources = {
        "https://shiftleft.io/codepropertygraph/schema/dialect/2026-10" => {
            path = "schemas/cpg-dialect.meta.schema.json"
        },
        "https://shiftleft.io/codepropertygraph/schema/meta/cpg-schema-vocabulary/2026-10" => {
            path = "schemas/cpg-schema.vocabulary.meta.schema.json"
        }
    },
    vocabularies = [
        "https://shiftleft.io/codepropertygraph/schema/vocab/cpg-schema/2026-10"
    ],
    keywords = {
        "cpg:domainShortName" => crate::json_vocabulary::annotation_keyword,
        "cpg:basePackage" => crate::json_vocabulary::annotation_keyword,
        "cpg:additionalTraversalsPackages" => crate::json_vocabulary::annotation_keyword,
        "cpg:modules" => crate::json_vocabulary::annotation_keyword,
        "cpg:dependsOn" => crate::json_vocabulary::annotation_keyword,
        "cpg:propertyDefaults" => crate::json_vocabulary::annotation_keyword
    }
)]
pub struct CanonicalCpgSchemaValidator;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct JsonModule {
    name: String,
    dependencies_owned: Vec<String>,
    dependencies: Vec<&'static str>,
}

impl JsonModule {
    fn new(name: String, dependencies_owned: Vec<String>) -> Self {
        // `SchemaModuleContract` intentionally exposes `&[&str]`. To keep the
        // JSON adapter owned and simple, strings are leaked for the adapter's
        // process lifetime. This adapter is intended for static schema
        // documents; native code should prefer `NativeCpgSchema`.
        let dependencies = dependencies_owned
            .iter()
            .cloned()
            .map(|s| Box::leak(s.into_boxed_str()) as &'static str)
            .collect();
        Self { name, dependencies_owned, dependencies }
    }
}

impl SchemaModuleContract for JsonModule {
    fn name(&self) -> &str {
        &self.name
    }

    fn dependencies(&self) -> &[&str] {
        &self.dependencies
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct JsonPropertyDefaults {
    string: String,
    boolean: bool,
    byte: i8,
    short: i16,
    int: i32,
    long: i64,
    float: f32,
    double: f64,
    char_: char,
}

impl PropertyDefaultsContract for JsonPropertyDefaults {
    fn string_default(&self) -> &str { &self.string }
    fn boolean_default(&self) -> bool { self.boolean }
    fn byte_default(&self) -> i8 { self.byte }
    fn short_default(&self) -> i16 { self.short }
    fn int_default(&self) -> i32 { self.int }
    fn long_default(&self) -> i64 { self.long }
    fn float_default(&self) -> f32 { self.float }
    fn double_default(&self) -> f64 { self.double }
    fn char_default(&self) -> char { self.char_ }
}

#[derive(Clone, Debug, PartialEq)]
pub struct JsonCpgSchema {
    domain_short_name: String,
    base_package: String,
    traversal_packages_owned: Vec<String>,
    traversal_packages: Vec<&'static str>,
    modules: Vec<JsonModule>,
    defaults: JsonPropertyDefaults,
}

impl CpgSchemaContract for JsonCpgSchema {
    type Module = JsonModule;
    type Defaults = JsonPropertyDefaults;

    fn domain_short_name(&self) -> &str {
        &self.domain_short_name
    }

    fn base_package(&self) -> &str {
        &self.base_package
    }

    fn additional_traversals_packages(&self) -> &[&str] {
        &self.traversal_packages
    }

    fn modules(&self) -> &[Self::Module] {
        &self.modules
    }

    fn property_defaults(&self) -> &Self::Defaults {
        &self.defaults
    }
}

#[derive(Debug)]
pub enum JsonBindingError {
    MetaSchema(String),
    Missing(&'static str),
    Invalid(&'static str),
    Contract(ContractError),
}

impl fmt::Display for JsonBindingError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::MetaSchema(message) => write!(f, "JSON schema contract violation: {message}"),
            Self::Missing(field) => write!(f, "missing required field {field}"),
            Self::Invalid(field) => write!(f, "invalid field {field}"),
            Self::Contract(error) => error.fmt(f),
        }
    }
}

impl std::error::Error for JsonBindingError {}

impl From<ContractError> for JsonBindingError {
    fn from(value: ContractError) -> Self {
        Self::Contract(value)
    }
}

fn string_field<'a>(value: &'a Value, key: &'static str) -> Result<&'a str, JsonBindingError> {
    value.get(key).and_then(Value::as_str).ok_or(JsonBindingError::Missing(key))
}

fn integer_field(value: &Value, key: &'static str) -> Result<i64, JsonBindingError> {
    value.get(key).and_then(Value::as_i64).ok_or(JsonBindingError::Invalid(key))
}

impl JsonCpgSchema {
    /// Parse a JSON representation and expose it through the common Rust traits.
    pub fn from_value(value: &Value) -> Result<Self, JsonBindingError> {
        CpgSchemaMetaSchemaValidator::validate(value)
            .map_err(|error| JsonBindingError::MetaSchema(error.to_string()))?;

        let domain_short_name = string_field(value, "cpg:domainShortName")?.to_owned();
        let base_package = string_field(value, "cpg:basePackage")?.to_owned();

        let traversal_packages_owned = value["cpg:additionalTraversalsPackages"]
            .as_array()
            .ok_or(JsonBindingError::Invalid("cpg:additionalTraversalsPackages"))?
            .iter()
            .map(|v| {
                v.as_str()
                    .map(ToOwned::to_owned)
                    .ok_or(JsonBindingError::Invalid("cpg:additionalTraversalsPackages"))
            })
            .collect::<Result<Vec<_>, _>>()?;

        let traversal_packages = traversal_packages_owned
            .iter()
            .cloned()
            .map(|s| Box::leak(s.into_boxed_str()) as &'static str)
            .collect();

        let modules = value["cpg:modules"]
            .as_array()
            .ok_or(JsonBindingError::Invalid("cpg:modules"))?
            .iter()
            .map(|module| {
                let name = string_field(module, "name")?.to_owned();
                let deps = module["cpg:dependsOn"]
                    .as_array()
                    .ok_or(JsonBindingError::Invalid("cpg:dependsOn"))?
                    .iter()
                    .map(|v| {
                        v.as_str()
                            .map(ToOwned::to_owned)
                            .ok_or(JsonBindingError::Invalid("cpg:dependsOn"))
                    })
                    .collect::<Result<Vec<_>, _>>()?;
                Ok(JsonModule::new(name, deps))
            })
            .collect::<Result<Vec<_>, JsonBindingError>>()?;

        let d = &value["cpg:propertyDefaults"];
        let char_text = string_field(d, "Char")?;
        let mut chars = char_text.chars();
        let char_ = chars.next().ok_or(JsonBindingError::Invalid("Char"))?;
        if chars.next().is_some() {
            return Err(JsonBindingError::Invalid("Char"));
        }

        let defaults = JsonPropertyDefaults {
            string: string_field(d, "String")?.to_owned(),
            boolean: d["Boolean"].as_bool().ok_or(JsonBindingError::Invalid("Boolean"))?,
            byte: i8::try_from(integer_field(d, "Byte")?).map_err(|_| JsonBindingError::Invalid("Byte"))?,
            short: i16::try_from(integer_field(d, "Short")?).map_err(|_| JsonBindingError::Invalid("Short"))?,
            int: i32::try_from(integer_field(d, "Int")?).map_err(|_| JsonBindingError::Invalid("Int"))?,
            long: integer_field(d, "Long")?,
            float: d["Float"].as_f64().ok_or(JsonBindingError::Invalid("Float"))? as f32,
            double: d["Double"].as_f64().ok_or(JsonBindingError::Invalid("Double"))?,
            char_,
        };

        let parsed = Self {
            domain_short_name,
            base_package,
            traversal_packages_owned,
            traversal_packages,
            modules,
            defaults,
        };

        validate_contract(&parsed)?;
        Ok(parsed)
    }

    pub fn canonical() -> Result<Self, JsonBindingError> {
        let value: Value = serde_json::from_str(CANONICAL_CPG_SCHEMA_JSON)
            .map_err(|error| JsonBindingError::MetaSchema(error.to_string()))?;
        Self::from_value(&value)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        contracts::{CpgSchemaContract, PropertyDefaultsContract},
        native::INSTANCE,
    };

    #[test]
    fn canonical_json_implements_common_contract() {
        let json = JsonCpgSchema::canonical().unwrap();
        assert_eq!(json.domain_short_name(), INSTANCE.domain_short_name());
        assert_eq!(json.base_package(), INSTANCE.base_package());
        assert_eq!(json.modules().len(), INSTANCE.modules().len());
    }

    #[test]
    fn json_property_defaults_match_native() {
        let json = JsonCpgSchema::canonical().unwrap();
        let jd = json.property_defaults();
        let nd = INSTANCE.property_defaults();

        assert_eq!(jd.string_default(), nd.string_default());
        assert_eq!(jd.boolean_default(), nd.boolean_default());
        assert_eq!(jd.byte_default(), nd.byte_default());
        assert_eq!(jd.short_default(), nd.short_default());
        assert_eq!(jd.int_default(), nd.int_default());
        assert_eq!(jd.long_default(), nd.long_default());
        assert_eq!(jd.float_default(), nd.float_default());
        assert_eq!(jd.double_default(), nd.double_default());
        assert_eq!(jd.char_default(), nd.char_default());
    }
}
